import numpy as np
from power import calib_intercept, expit
rng=np.random.default_rng(5)
def run(R,D,k,p0,rho,sv=0.3,nsim=250,B=500,su=1.2,sw=0.6,sz=0.8):
    a_c=calib_intercept(p0,su,sw,sz,sv); a_s=calib_intercept(p0*rho,su,sw,sz,sv)
    al=np.array([a_s,a_c,a_c]); sup=0; lbs=[]; ubs=[]; pts=[]
    for s in range(nsim):
        u=rng.normal(0,su,D); w=rng.normal(0,sw,(3,D)); v=rng.normal(0,sv,(3,R)); z=rng.normal(0,sz,(3,R,D))
        F=rng.binomial(k,expit(al[:,None,None]+u+w[:,None,:]+v[:,:,None]+z))
        ri=rng.integers(0,R,(B,3,R)); di=rng.integers(0,D,(B,D)); Fb=np.empty((B,3))
        for c in range(3):
            g=F[c][ri[:,c,:]]; g=np.take_along_axis(g,np.broadcast_to(di[:,None,:],(B,R,D)),axis=2); Fb[:,c]=g.sum((1,2))
        ok=True
        for c in (1,2):
            r=(Fb[:,0]+.5)/(Fb[:,c]+.5); ub=np.quantile(r,.975); ok&= ub<1
            if c==1: lbs.append(np.quantile(r,.025)); ubs.append(ub); pts.append((F[0].sum()+.5)/(F[1].sum()+.5))
        sup+=ok
    return sup/nsim, np.median(lbs), np.median(pts), np.median(ubs)
for R,D,k in ((3,40,3),(3,40,2),(5,40,3)):
    for rho in (0.8,0.7,0.6,0.5,0.4):
        p,lb,pt,ub=run(R,D,k,0.35,rho)
