                    started = False; notes = []
                    for line in open(f):
                        e = json.loads(line); p = e.get("payload") or {}
                        if e.get("type") != "response_item" or p.get("type") != "message": continue
                        txt = "".join(c.get("text", "") for c in p.get("content", []) if isinstance(c, dict))
